import { Hono } from 'hono';
import { cors } from 'hono/cors';

// `Env` comes from worker-configuration.d.ts (generated by `npm run types`):
// env.DB is the D1 database, env.BUCKET the R2 bucket.
const app = new Hono<{ Bindings: Env }>();

app.use('*', cors());

const ALLOWED_TYPES: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/gif': 'gif',
  'image/webp': 'webp',
};

// Until auth exists (step 5), everything is posted as the demo user.
const currentUserId = () => 'demo';

app.get('/', (c) => c.json({ ok: true, service: 'memes-api' }));

/**
 * PUT /uploads  (body = raw image bytes, Content-Type = image/*)
 * Streams the image into R2 and returns its key.
 * Later you can swap this for presigned URLs so the bytes skip the Worker.
 */
app.put('/uploads', async (c) => {
  const type = c.req.header('content-type')?.split(';')[0] ?? '';
  const ext = ALLOWED_TYPES[type];
  if (!ext) return c.json({ error: 'Unsupported image type' }, 415);

  const size = Number(c.req.header('content-length') ?? 0);
  if (size > Number(c.env.MAX_UPLOAD_BYTES)) return c.json({ error: 'File too large' }, 413);

  const body = c.req.raw.body;
  if (!body) return c.json({ error: 'Empty body' }, 400);

  const key = `memes/${crypto.randomUUID()}.${ext}`;
  await c.env.BUCKET.put(key, body, { httpMetadata: { contentType: type } });
  return c.json({ key }, 201);
});

/** POST /posts  { key, caption } -> creates the post row in D1 */
app.post('/posts', async (c) => {
  const { key, caption } = await c.req.json<{ key?: string; caption?: string }>();
  if (!key || !key.startsWith('memes/')) return c.json({ error: 'Missing key' }, 400);

  // make sure the file was actually uploaded
  const head = await c.env.BUCKET.head(key);
  if (!head) return c.json({ error: 'Upload not found' }, 404);

  const id = crypto.randomUUID();
  const now = Date.now();
  await c.env.DB.prepare(
    'INSERT INTO posts (id, user_id, image_key, caption, created_at) VALUES (?, ?, ?, ?, ?)',
  )
    .bind(id, currentUserId(), key, caption?.slice(0, 280) || null, now)
    .run();

  const post = await findPost(c.env.DB, id);
  return c.json(post && toApi(post, imageBase(c.req.url)), 201);
});

/** GET /posts?cursor=<createdAt>  -> newest first, 20 per page */
app.get('/posts', async (c) => {
  const cursor = Number(c.req.query('cursor')) || Number.MAX_SAFE_INTEGER;
  const limit = 20;
  const { results } = await c.env.DB.prepare(`${POST_SELECT} WHERE p.created_at < ? ORDER BY p.created_at DESC LIMIT ?`)
    .bind(cursor, limit)
    .all<PostRow>();

  const base = imageBase(c.req.url);
  return c.json({
    posts: results.map((r) => toApi(r, base)),
    nextCursor: results.length === limit ? results[results.length - 1].created_at : null,
  });
});

/**
 * GET /images/memes/<file>  -> serves the image from R2.
 * Fine for development. In production, connect a custom domain to the bucket
 * so images come straight from Cloudflare's CDN instead of through the Worker.
 */
app.get('/images/*', async (c) => {
  const key = c.req.path.replace('/images/', '');
  const obj = await c.env.BUCKET.get(key);
  if (!obj) return c.notFound();
  const headers = new Headers();
  obj.writeHttpMetadata(headers);
  headers.set('etag', obj.httpEtag);
  headers.set('cache-control', 'public, max-age=31536000, immutable');
  return new Response(obj.body, { headers });
});

// ---------- helpers ----------

type PostRow = {
  id: string;
  image_key: string;
  caption: string | null;
  created_at: number;
  handle: string;
  likes: number;
  comments: number;
};

const POST_SELECT = `
  SELECT p.id, p.image_key, p.caption, p.created_at, u.handle,
         (SELECT COUNT(*) FROM likes l WHERE l.post_id = p.id)    AS likes,
         (SELECT COUNT(*) FROM comments m WHERE m.post_id = p.id) AS comments
  FROM posts p JOIN users u ON u.id = p.user_id`;

const findPost = (db: D1Database, id: string) =>
  db.prepare(`${POST_SELECT} WHERE p.id = ?`).bind(id).first<PostRow>();

const imageBase = (url: string) => `${new URL(url).origin}/images/`;

const toApi = (r: PostRow, base: string) => ({
  id: r.id,
  imageUrl: base + r.image_key,
  caption: r.caption,
  handle: r.handle,
  createdAt: r.created_at,
  likes: r.likes,
  comments: r.comments,
});

export default app;
